{
  "cards": [
    {
      "node_code": "N_26bb156ba0520a79",
      "definition": "研究利用超声波在金属介质中传播特性，对钢结构及焊缝内部缺陷（如裂纹、气孔、夹渣）进行探测、定位与定量分析的技术原理、仪器参数及操作规范。",
      "boundary": "本节点聚焦于超声物理方法在钢结构无损检测中的具体应用。核心在于声波与金属材料的相互作用机制、探头选型、耦合剂使用及信号解读。与“回弹检测”的区别在于检测对象为金属内部而非表面硬度；与“雷达检测”的区别在于利用声波而非电磁波。不包含基于超声数据的缺陷定性算法开发或结构整体安全鉴定。",
      "includes": [
        "钢结构焊缝的A型、B型、C型及相控阵超声检测原理与标准",
        "超声探头、仪器参数设置及在金属结构中的适用性分析"
      ],
      "excludes": [
        "基于超声数据的缺陷自动识别算法或人工智能模型（归入缺陷识别）",
        "利用超声数据出具的结构安全性等级评定报告（归入工程鉴定与安全评估）"
      ],
      "sibling_distinctions": [
        {
          "other_code": "N_2801fab168ba0010",
          "rule": "本节点利用声波探测金属内部缺陷；兄弟节点利用机械冲击测量表面硬度或强度，主要适用于混凝土，在钢结构中应用极少。"
        },
        {
          "other_code": "N_00f98170b8b906e",
          "rule": "本节点利用声波，穿透力强，适合厚壁金属内部检测；兄弟节点利用电磁波，适合浅层或非金属界面检测，在金属中衰减极快。"
        }
      ],
      "cross_boundary_rule": "若内容涉及超声在钢结构中的具体检测工艺、波形分析或标准操作，主挂载本节点；若仅讨论超声物理基础理论而不涉及工程应用，则需视情况归入基础理论或保留在本节点作为背景知识。"
    },
    {
      "node_code": "N_2801fab168ba0010",
      "definition": "研究利用回弹仪测量结构表面硬度，进而推定材料强度或状态的非破损检测技术，在钢结构领域主要涉及表面硬度测试及与强度的相关性分析。",
      "boundary": "本节点聚焦于回弹法这一特定机械检测手段。虽然回弹法在混凝土检测中最为常见，但在本树结构中位于“钢结构与焊缝检测”下，因此特指其在金属结构表面硬度、加工硬化程度或残余应力状态评估中的应用。与“超声检测”的区别在于检测对象为表面而非内部；与“雷达检测”的区别在于利用机械能而非电磁能。",
      "includes": [
        "钢结构表面硬度回弹测试原理及仪器校准",
        "回弹值与钢材强度、硬度或表面状态的相关性研究"
      ],
      "excludes": [
        "混凝土结构强度的回弹检测（归入混凝土结构现场检测）",
        "基于回弹数据的结构整体承载力计算（归入工程鉴定与安全评估）"
      ],
      "sibling_distinctions": [
        {
          "other_code": "N_26bb156ba0520a79",
          "rule": "本节点侧重表面机械性能（硬度）的快速评估；兄弟节点侧重内部缺陷的精确探测。"
        },
        {
          "other_code": "N_00f98170b8b906e",
          "rule": "本节点利用机械冲击；兄弟节点利用电磁波。回弹法在金属中主要用于表面状态，雷达法在金属中应用受限。"
        }
      ],
      "cross_boundary_rule": "若内容明确针对钢结构表面硬度或强度推定，主挂载本节点；若内容混淆了混凝土回弹与钢结构回弹，需根据实际检测对象判断，若为混凝土则应归入混凝土检测分支。"
    },
    {
      "node_code": "N_00f98170b8b906e",
      "definition": "研究利用高频电磁波（雷达）对钢结构表面及近表面缺陷、涂层厚度或内部分层进行探测的技术原理、信号处理及适用性分析。",
      "boundary": "本节点聚焦于雷达（GPR）技术在钢结构无损检测中的应用。由于电磁波在金属中衰减极快，本节点内容主要涉及雷达在钢结构防腐层、复合结构界面或浅层表面缺陷检测中的应用，以及信号反射机制。与“超声检测”的区别在于利用电磁波而非声波；与“回弹检测”的区别在于非接触式电磁探测而非机械接触。",
      "includes": [
        "雷达在钢结构防腐层厚度、空鼓或浅层缺陷检测中的应用",
        "雷达信号在金属及非金属复合材料中的传播特性与解释"
      ],
      "excludes": [
        "雷达在混凝土或岩土工程中的深层探测（归入相应材料检测节点）",
        "基于雷达图像的深度缺陷自动识别算法（归入缺陷识别）"
      ],
      "sibling_distinctions": [
        {
          "other_code": "N_26bb156ba0520a79",
          "rule": "本节点利用电磁波，受金属屏蔽效应影响大，多用于表面或非金属覆盖层；兄弟节点利用声波，可穿透金属内部。"
        },
        {
          "other_code": "N_2801fab168ba0010",
          "rule": "本节点为非接触式电磁探测；兄弟节点为接触式机械测试。"
        }
      ],
      "cross_boundary_rule": "若内容涉及雷达在钢结构表面或涂层检测中的具体应用，主挂载本节点；若内容讨论雷达在混凝土中的深层探测，则应归入混凝土检测或通用雷达检测节点（若存在）。"
    }
  ]
}
